  {
    "statement_index": 1,
    "statement": {
      "subject": {
        "value": "The Land of Gorch",
        "evidence": [
          {
            "segment": "title",
            "quote": "The Land of Gorch",
            "occurrence": 1
          }
        ]
      },
      "predicate": {
        "value": "appearedIn",
        "evidence": [
          {
            "segment": "text",
